#!/bin/bash
# Regenerate the editor's embedded fonts: subset Noto Sans / Sans Bold / Sans Mono (SIL OFL 1.1, see LICENSE) to the
# ranges the editor can show, then compress them into editor_fonts.inc with Dear ImGui's binary_to_compressed_c.
#   regen.sh <path to noto .ttf dir> <path to imgui misc/fonts/binary_to_compressed_c.cpp>
set -eu
cd "$(dirname "$0")"
SRC="${1:-/usr/share/fonts/noto}"; TOOL_SRC="${2:?binary_to_compressed_c.cpp}"
U="U+0020-007E,U+00A0-024F,U+0370-03FF,U+0400-04FF,U+1E00-1EFF,U+2000-206F,U+20A0-20CF,U+2100-214F,U+2190-21FF,U+2200-22FF,U+2300-23FF,U+2460-24FF,U+2500-257F,U+25A0-25FF,U+2600-26FF,U+2700-27BF,U+FFFD"
for f in NotoSans-Regular NotoSans-Bold NotoSansMono-Regular; do
    pyftsubset "$SRC/$f.ttf" --unicodes="$U" --no-hinting --layout-features='kern,liga' --output-file="$f.ttf"
done
T=$(mktemp -d); g++ -O1 -o "$T/b2c" "$TOOL_SRC"
{ echo "// Generated by imgui/misc/fonts/binary_to_compressed_c from the subset Noto fonts in this directory (SIL OFL 1.1,"
  echo "// see LICENSE). Regenerate with third_party/fonts/regen.sh."
  "$T/b2c" NotoSans-Regular.ttf NotoSansRegular
  "$T/b2c" NotoSans-Bold.ttf NotoSansBold
  "$T/b2c" NotoSansMono-Regular.ttf NotoSansMono; } > editor_fonts.inc
rm -rf "$T"
